 = 3\n        min_obs = lag * k + k + 1\n        if T < min_obs:\n            results[lag] = {\"p_value\": np.nan, \"F_stat\": np.nan, \"df\": (np.nan, np.nan),\n                           \"note\": f\"T={T} too small for lag={lag}\"}\n            continue\n        try:\n            model = VAR(sub[[effect, cause, condition]])\n            fitted = model.fit(lag)\n            test = fitted.test_causality(caused=effect, causing=cause, kind='f')\n            results[lag] = {\n                \"p_value\": test.pvalue,\n                \"F_stat\": test.test_statistic,\n                \"df\": (test.df_num, test.df_denom),\n            }\n        except Exception as e:\n            results[lag] = {\"p_value\": np.nan, \"F_stat\": np.nan, \"note\": str(e)[:80]}\n\n    return results\n\n\ndef unconditional_granger(df, cause, effect, maxlag=2):\n    cols = [cause, effect]\n    if any(c not in df.columns for c in cols):\n        return None\n    sub = df[cols].dropna()\n    T = len(sub)\n    results = {}\n    for lag in range(1, maxlag + 1):\n        k = 2\n        min_obs = lag * k + k + 1\n        if T < min_obs:\n            results[lag] = {\"p_value\": np.nan, \"F_stat\": np.nan,\n                           \"note\": f\"T={T} too small for lag={lag}\"}\n            continue\n        try:\n            model = VAR(sub[[effect, cause]])\n            fitted = model.fit(lag)\n            test = fitted.test_causality(caused=effect, causing=cause, kind='f')\n            results[lag] = {\n                \"p_value\": test.pvalue,\n                \"F_stat\": test.test_statistic,\n                \"df\": (test.df_num, test.df_denom),\n            }\n        except Exception as e:\n            results[lag] = {\"p_value\": np.nan, \"F_stat\": np.nan, \"note\": str(e)[:80]}\n    return results\n\n\ndef joint_granger(df, causes, effect, maxlag=2):\n    cols = [effect] + causes\n    if any(c not in df.columns for c in cols):\n        return None\n    sub = df[cols].dropna()\n    T = len(sub)\n    results = {}\n    for lag in range(1, maxlag + 1):\n        k = len(cols)\n        min_obs = lag * k + k + 1\n        if T < min_obs:\n            results[lag] = {\"p_value\": np.nan, \"F_stat\": np.nan,\n                           \"note\": f\"T={T} too small for lag={lag}\"}\n            continue\n        try:\n            model = VAR(sub)\n            fitted = model.fit(lag)\n            test = fitted.test_causality(caused=effect, causing=causes, kind='f')\n            results[lag] = {\n                \"p_value\": test.pvalue,\n                \"F_stat\": test.test_statistic,\n                \"df\": (test.df_num, test.df_denom),\n            }\n        except Exception as e:\n            results[lag] = {\"p_value\": np.nan, \"F_stat\": np.nan, \"note\": str(e)[:80]}\n    return results\n\n\n# ─── Main analysis ───\nprint(\"=\" * 80)\nprint(\"CONDITIONAL GRANGER CAUSALITY: token_entropy vs ECE → diversity\")\nprint(\"=\" * 80)\n\nall_results = {}\nmissing = []\n\nfor exp_name, path in EXPERIMENTS.items():\n    if not os.path.exists(path):\n        missing.append(exp_name)\n        print(f\"\\n  MISSING: {exp_name} → {path}\")\n        continue\n\n    df = load_experiment(path)\n    T = len(df)\n    print(f\"\\n  {exp_name} (T={T}):\")\n\n    exp_results = {\"T\": T, \"tests\": {}}\n\n    for downstream in DOWNSTREAMS:\n        if downstream not in df.columns:\n            continue\n\n        tests = {}\n        tests[\"uncond_entropy\"] = unconditional_granger(df, \"token_entropy\", downstream)\n        tests[\"uncond_ece\"] = unconditional_granger(df, \"ece\", downstream)\n        tests[\"cond_entropy_given_ece\"] = conditional_granger(df, \"token_entropy\", downstream, \"ece\")\n        tests[\"cond_ece_given_entropy\"] = conditional_granger(df, \"ece\", downstream, \"token_entropy\")\n        tests[\"joint\"] = joint_granger(df, [\"token_entropy\", \"ece\"], downstream)\n\n        exp_results[\"tests\"][downstream] = tests\n\n        for test_nam